CREATE TABLE IF NOT EXISTS hr_offboarding_plans (
 id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,company_id TEXT NOT NULL REFERENCES companies(id) ON DELETE RESTRICT,branch_id TEXT NOT NULL REFERENCES branches(id) ON DELETE RESTRICT,staff_id TEXT NOT NULL REFERENCES staff(id) ON DELETE CASCADE,termination_date DATE NOT NULL,termination_reason TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'ACTIVE',final_payroll_status TEXT NOT NULL DEFAULT 'PENDING',leave_settlement_status TEXT NOT NULL DEFAULT 'PENDING',advance_expense_status TEXT NOT NULL DEFAULT 'PENDING',access_closure_status TEXT NOT NULL DEFAULT 'PENDING',asset_return_status TEXT NOT NULL DEFAULT 'PENDING',personnel_file_status TEXT NOT NULL DEFAULT 'PENDING',completed_at TIMESTAMP(3),created_by TEXT,created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT hr_offboarding_status_chk CHECK(status IN ('DRAFT','ACTIVE','COMPLETED','CANCELLED')));
CREATE UNIQUE INDEX IF NOT EXISTS hr_offboarding_active_staff_idx ON hr_offboarding_plans(tenant_id,staff_id) WHERE status='ACTIVE';CREATE INDEX IF NOT EXISTS hr_offboarding_staff_idx ON hr_offboarding_plans(tenant_id,staff_id,termination_date DESC);
CREATE TABLE IF NOT EXISTS hr_offboarding_tasks (
 id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,plan_id TEXT NOT NULL REFERENCES hr_offboarding_plans(id) ON DELETE CASCADE,task_type TEXT NOT NULL,title TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'PENDING',owner_staff_id TEXT REFERENCES staff(id) ON DELETE SET NULL,due_date DATE,completion_note TEXT,completed_by TEXT,completed_at TIMESTAMP(3),sort_order INTEGER NOT NULL DEFAULT 0,created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT hr_offboarding_task_status_chk CHECK(status IN ('PENDING','IN_PROGRESS','COMPLETED','SKIPPED','BLOCKED')));
CREATE INDEX IF NOT EXISTS hr_offboarding_tasks_plan_idx ON hr_offboarding_tasks(tenant_id,plan_id,sort_order);
